-- R1 to R12 and their teaching weeks. Numbers are never reused.
-- Each teaching week is a real foreign key onto a graded week, so the app can count how many times a rule has fired.
INSERT INTO macro_core.scenario_rule (number, text, retired_week)
VALUES (1, 'Compute a futures-quoted index''s weekly % change from the cash index, never from the front-month future; contract rolls contaminate the WoW math.', NULL)
ON CONFLICT (number) DO UPDATE SET
    text = EXCLUDED.text,
    retired_week = EXCLUDED.retired_week;
INSERT INTO macro_core.scenario_rule (number, text, retired_week)
VALUES (2, 'The scenario set must span both directions of the dominant swing variable. Two-sided is a requirement, not a stylistic preference.', NULL)
ON CONFLICT (number) DO UPDATE SET
    text = EXCLUDED.text,
    retired_week = EXCLUDED.retired_week;
INSERT INTO macro_core.scenario_rule (number, text, retired_week)
VALUES (3, 'Oil bands must be wide enough to survive a chokepoint headline in either direction. Both Hormuz reopening and a second front (Bab el-Mandeb) broke bands that every branch shared. Size the band from the last 8 weeks of Brent range, not from the current narrative.', NULL)
ON CONFLICT (number) DO UPDATE SET
    text = EXCLUDED.text,
    retired_week = EXCLUDED.retired_week;
INSERT INTO macro_core.scenario_rule (number, text, retired_week)
VALUES (4, 'Every risk-off trigger needs a confirming-regime clause: a price level alone is not a trigger. Pair it with at least one of VIX above a stated level, HY OAS above a stated level, or breadth below a stated level.', NULL)
ON CONFLICT (number) DO UPDATE SET
    text = EXCLUDED.text,
    retired_week = EXCLUDED.retired_week;
INSERT INTO macro_core.scenario_rule (number, text, retired_week)
VALUES (5, 'Leadership gets its own two-sided axis, separate from the macro trigger. A correct macro branch and a correct tape have landed in different scenarios three times; the relative trade (MSFT vs META, merchant vs custom silicon) cannot be expressed in a directional-only table, and in W38 the split ran along the volatility-and-crypto axis rather than single-stock leadership.', NULL)
ON CONFLICT (number) DO UPDATE SET
    text = EXCLUDED.text,
    retired_week = EXCLUDED.retired_week;
INSERT INTO macro_core.scenario_rule (number, text, retired_week)
VALUES (6, 'Reserve explicit probability for a dateless structural shock (a model release, a DUV breakthrough, a sanctions design). Two of the last ten weeks were driven by an event no calendar carried.', NULL)
ON CONFLICT (number) DO UPDATE SET
    text = EXCLUDED.text,
    retired_week = EXCLUDED.retired_week;
INSERT INTO macro_core.scenario_rule (number, text, retired_week)
VALUES (7, 'When equities and crypto sit on opposite sides of the swing variable, give them separate target rows rather than a decoupling footnote.', NULL)
ON CONFLICT (number) DO UPDATE SET
    text = EXCLUDED.text,
    retired_week = EXCLUDED.retired_week;
INSERT INTO macro_core.scenario_rule (number, text, retired_week)
VALUES (8, 'When a phase falsifier is a conjunction (reclaim AND flow), price the case where both arrive in the same week; a Lull call with no mechanism for a +20% week is not a call.', NULL)
ON CONFLICT (number) DO UPDATE SET
    text = EXCLUDED.text,
    retired_week = EXCLUDED.retired_week;
INSERT INTO macro_core.scenario_rule (number, text, retired_week)
VALUES (9, 'Do not couple an index direction to a specific leadership regime continuing; leadership flips faster than phase calls.', NULL)
ON CONFLICT (number) DO UPDATE SET
    text = EXCLUDED.text,
    retired_week = EXCLUDED.retired_week;
INSERT INTO macro_core.scenario_rule (number, text, retired_week)
VALUES (10, 'Do not extrapolate a three-week flow streak into a regime; streaks inflect exactly when they look most established.', NULL)
ON CONFLICT (number) DO UPDATE SET
    text = EXCLUDED.text,
    retired_week = EXCLUDED.retired_week;
INSERT INTO macro_core.scenario_rule (number, text, retired_week)
VALUES (11, 'Oil gets its own two-sided axis, separate from the risk-off tail. The oil trigger has fired inside the tail scenario six weeks running while that tail''s equity, credit and vol legs never fired: crude is an inflation-and-rates variable that only sometimes becomes a risk variable, so pricing it only inside the risk-off branch guarantees a Partial.', NULL)
ON CONFLICT (number) DO UPDATE SET
    text = EXCLUDED.text,
    retired_week = EXCLUDED.retired_week;
INSERT INTO macro_core.scenario_rule (number, text, retired_week)
VALUES (12, 'Name the dominant driver per asset and state which channel its band is priced off. BTC was capped at $79K off the rates channel in the week the SEC''s agency track drove it; oil was priced off sanctions in the week reopening hopes drove it. When an asset has a live policy or regulatory channel of its own alongside the macro one, price the band off the channel that moved it last, or widen it to span both.', NULL)
ON CONFLICT (number) DO UPDATE SET
    text = EXCLUDED.text,
    retired_week = EXCLUDED.retired_week;
